package dev.thefoolish.generated.anishelf;
public final class ExtensionRecord{public enum State{AVAILABLE,INSTALLED,ENABLED,DISABLED,FAILED}public final String id,name,version,repoUrl,searchUrl,playbackUrl;public State state;public String error;public ExtensionRecord(String id,String name,String version,String repoUrl,String searchUrl,String playbackUrl){this.id=id;this.name=name;this.version=version;this.repoUrl=repoUrl;this.searchUrl=searchUrl==null?"":searchUrl;this.playbackUrl=playbackUrl==null?"":playbackUrl;this.state=State.AVAILABLE;this.error="";}public boolean searchable(){return searchUrl.length()>0;}public boolean playable(){return playbackUrl.length()>0;}}
